cat > internal/hosts/profile.go <<'EOF'
package hosts

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"regexp"
	"sort"
	"strings"
)

// Entry represents a single host entry (IP -> domain mapping).
type Entry struct {
	IP     string
	Domain string
}

// Profile represents a named profile with entries and a status.
type Profile struct {
	Name    string
	Status  string // "on" or "off"
	IPs     []string
	IPMap   map[string][]string // ip -> list of domains in insertion order
}

// File represents a parsed hosts file.
type File struct {
	Path         string
	DefaultLines []string // raw lines in the "default" section (before the header)
	Profiles     []*Profile // named profiles in file order
	profByName   map[string]*Profile
}

// NewFile creates an empty File structure.
func NewFile(path string) *File {
	return &File{
		Path:       path,
		profByName: map[string]*Profile{},
	}
}

// newProfile creates an empty Profile.
func newProfile(name, status string) *Profile {
	return &Profile{
		Name:   name,
		Status: status,
		IPMap:  map[string][]string{},
	}
}

// AddEntry adds (ip, domain) to the profile; dedups and preserves IP insertion order.
func (p *Profile) AddEntry(ip, domain string) {
	if _, ok := p.IPMap[ip]; !ok {
		p.IPs = append(p.IPs, ip)
		p.IPMap[ip] = []string{}
	}
	for _, d := range p.IPMap[ip] {
		if d == domain {
			return
		}
	}
	p.IPMap[ip] = append(p.IPMap[ip], domain)
}

// RemoveDomain removes domain from all IPs in the profile. Empty IPs get removed.
func (p *Profile) RemoveDomain(domain string) {
	for _, ip := range p.IPs {
		arr := p.IPMap[ip]
		out := arr[:0]
		for _, d := range arr {
			if d != domain {
				out = append(out, d)
			}
		}
		if len(out) == 0 {
			delete(p.IPMap, ip)
		} else {
			p.IPMap[ip] = out
		}
	}
	ips := p.IPs[:0]
	for _, ip := range p.IPs {
		if _, ok := p.IPMap[ip]; ok {
			ips = append(ips, ip)
		}
	}
	p.IPs = ips
}

// Entries returns all entries preserving insertion order.
func (p *Profile) Entries() []Entry {
	out := []Entry{}
	for _, ip := range p.IPs {
		for _, d := range p.IPMap[ip] {
			out = append(out, Entry{IP: ip, Domain: d})
		}
	}
	return out
}

// Count returns number of entries.
func (p *Profile) Count() int {
	n := 0
	for _, ip := range p.IPs {
		n += len(p.IPMap[ip])
	}
	return n
}

// GetProfile returns a profile by name.
func (f *File) GetProfile(name string) *Profile {
	return f.profByName[name]
}

// ProfileNames returns profile names in file order.
func (f *File) ProfileNames() []string {
	names := make([]string, 0, len(f.Profiles))
	for _, p := range f.Profiles {
		names = append(names, p.Name)
	}
	return names
}

// SortedProfileNames returns sorted profile names.
func (f *File) SortedProfileNames() []string {
	names := f.ProfileNames()
	sort.Strings(names)
	return names
}

// AddProfile adds a new profile (or replaces existing same-name one).
func (f *File) AddProfile(p *Profile) {
	if existing, ok := f.profByName[p.Name]; ok {
		// Replace in place in the slice
		for i, pp := range f.Profiles {
			if pp == existing {
				f.Profiles[i] = p
				break
			}
		}
	} else {
		f.Profiles = append(f.Profiles, p)
	}
	f.profByName[p.Name] = p
}

// RemoveProfile removes a profile by name.
func (f *File) RemoveProfile(name string) {
	if _, ok := f.profByName[name]; !ok {
		return
	}
	delete(f.profByName, name)
	out := f.Profiles[:0]
	for _, p := range f.Profiles {
		if p.Name != name {
			out = append(out, p)
		}
	}
	f.Profiles = out
}

// Header line for hostctl-managed section.
const managedHeader = "##################################################################\n" +
	"# Content under this line is handled by hostctl. DO NOT EDIT.\n" +
	"##################################################################\n"

var profileStartRe = regexp.MustCompile(`^#\s*profile\.(on|off)\s+(\S+)\s*$`)
var endRe = regexp.MustCompile(`^#\s*end\s*$`)

// Parse reads and parses the hosts file.
func Parse(path string) (*File, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return ParseReader(path, f)
}

// ParseReader parses hosts content from an io.Reader.
func ParseReader(path string, r io.Reader) (*File, error) {
	file := NewFile(path)
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 64*1024), 10*1024*1024)

	headerStart := "##################################################################"
	const (
		stateDefault = iota
		stateManaged
		stateInProfile
	)
	state := stateDefault
	var cur *Profile
	headerLines := 0 // how many consecutive header hash lines we've seen

	var defaultLines []string
	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		switch state {
		case stateDefault:
			if line == headerStart {
				headerLines++
				if headerLines == 1 {
					// Remove any trailing blank default lines we added
					for len(defaultLines) > 0 && strings.TrimSpace(defaultLines[len(defaultLines)-1]) == "" {
						defaultLines = defaultLines[:len(defaultLines)-1]
					}
				}
				continue
			}
			if headerLines >= 1 && (strings.HasPrefix(line, "# Content under") || headerLines == 2) {
				headerLines++
				if headerLines == 3 {
					state = stateManaged
				}
				continue
			}
			// Not part of the managed header; reset header counter
			if headerLines > 0 {
				headerLines = 0
			}
			defaultLines = append(defaultLines, line)
		case stateManaged:
			if trimmed == "" {
				continue
			}
			if m := profileStartRe.FindStringSubmatch(trimmed); m != nil {
				cur = newProfile(m[2], m[1])
				state = stateInProfile
				continue
			}
			// Unexpected content; store as default-like? The original likely keeps it in default
			// For safety, ignore.
		case stateInProfile:
			if endRe.MatchString(trimmed) {
				if cur != nil {
					file.AddProfile(cur)
					cur = nil
				}
				state = stateManaged
				continue
			}
			// Parse entry. Entries in disabled profiles have leading "# ".
			entryLine := trimmed
			if cur.Status == "off" {
				entryLine = strings.TrimPrefix(entryLine, "#")
				entryLine = strings.TrimSpace(entryLine)
			}
			if entryLine == "" {
				continue
			}
			if err := addEntryLine(cur, entryLine); err != nil {
				return nil, err
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}

	// If we were still building a profile (no # end), commit it.
	if cur != nil {
		file.AddProfile(cur)
	}

	file.DefaultLines = defaultLines
	return file, nil
}

// addEntryLine parses "IP host1 host2..." and adds them.
func addEntryLine(p *Profile, line string) error {
	fields := strings.Fields(line)
	if len(fields) < 2 {
		return nil
	}
	ip := fields[0]
	for _, d := range fields[1:] {
		if strings.HasPrefix(d, "#") {
			break
		}
		p.AddEntry(ip, d)
	}
	return nil
}

// Write serializes the hosts file to the path.
func (f *File) Write() error {
	var sb strings.Builder
	// Default section
	for i, l := range f.DefaultLines {
		sb.WriteString(l)
		if i < len(f.DefaultLines)-1 || !strings.HasSuffix(l, "\n") {
			sb.WriteString("\n")
		}
	}
	// If there are any profiles, write the header. Always include header after default even if none.
	sb.WriteString("\n")
	sb.WriteString(managedHeader)

	for _, p := range f.Profiles {
		sb.WriteString("\n")
		fmt.Fprintf(&sb, "# profile.%s %s\n", p.Status, p.Name)
		for _, ip := range p.IPs {
			for _, d := range p.IPMap[ip] {
				if p.Status == "off" {
					fmt.Fprintf(&sb, "# %s %s\n", ip, d)
				} else {
					fmt.Fprintf(&sb, "%s %s\n", ip, d)
				}
			}
		}
		sb.WriteString("# end\n")
	}

	return os.WriteFile(f.Path, []byte(sb.String()), 0644)
}

// ReadEntriesFile reads (IP, domain) entries from a simple hosts-like file.
func ReadEntriesFile(path string) ([][2]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	var out [][2]string
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		ip := fields[0]
		for _, d := range fields[1:] {
			if strings.HasPrefix(d, "#") {
				break
			}
			out = append(out, [2]string{ip, d})
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return out, nil
}
