package render

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"hostctl/internal/hosts"
)

// Row represents a single row of output.
type Row struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

// AllColumns are the columns in display order.
var AllColumns = []string{"profile", "status", "ip", "domain"}

// ColumnsForStatus for status view (no ip/domain).
var ColumnsForStatus = []string{"profile", "status"}

// columnTitle returns the uppercase title.
func columnTitle(c string) string { return strings.ToUpper(c) }

// columnValue returns the value for a row and column.
func columnValue(r Row, col string) string {
	switch col {
	case "profile":
		return r.Profile
	case "status":
		return r.Status
	case "ip":
		return r.IP
	case "domain":
		return r.Host
	}
	return ""
}

// FilterColumns reorders/filters all columns.
func FilterColumns(all []string, wanted []string) []string {
	if len(wanted) == 0 {
		return all
	}
	set := map[string]bool{}
	for _, c := range all {
		set[c] = true
	}
	out := []string{}
	for _, c := range wanted {
		lc := strings.ToLower(strings.TrimSpace(c))
		if set[lc] {
			out = append(out, lc)
		}
	}
	if len(out) == 0 {
		return all
	}
	return out
}

// RowGroup groups rows by profile.
type RowGroup struct {
	Name string
	Rows []Row
}

// BuildRows creates rows for the given profiles.
func BuildRows(profiles []*hosts.Profile, withEntries bool) []RowGroup {
	groups := []RowGroup{}
	for _, p := range profiles {
		g := RowGroup{Name: p.Name}
		if !withEntries {
			g.Rows = []Row{{Profile: p.Name, Status: p.Status}}
		} else {
			entries := p.Entries()
			if len(entries) == 0 {
				continue
			}
			for _, e := range entries {
				g.Rows = append(g.Rows, Row{
					Profile: p.Name,
					Status:  p.Status,
					IP:      e.IP,
					Host:    e.Domain,
				})
			}
		}
		groups = append(groups, g)
	}
	return groups
}

// Render prints in the requested format.
func Render(w io.Writer, groups []RowGroup, columns []string, format string) {
	switch format {
	case "json":
		renderJSON(w, groups, columns)
	case "raw":
		renderRaw(w, groups, columns)
	case "markdown":
		renderMarkdown(w, groups, columns)
	default:
		renderTable(w, groups, columns)
	}
}

func renderJSON(w io.Writer, groups []RowGroup, columns []string) {
	rows := []Row{}
	for _, g := range groups {
		rows = append(rows, g.Rows...)
	}
	if rows == nil {
		rows = []Row{}
	}
	data, _ := json.Marshal(rows)
	fmt.Fprintln(w, string(data))
}

func computeWidths(groups []RowGroup, columns []string) map[string]int {
	widths := map[string]int{}
	for _, c := range columns {
		widths[c] = len(columnTitle(c))
	}
	for _, g := range groups {
		for _, r := range g.Rows {
			for _, c := range columns {
				v := columnValue(r, c)
				if len(v) > widths[c] {
					widths[c] = len(v)
				}
			}
		}
	}
	return widths
}

func renderRaw(w io.Writer, groups []RowGroup, columns []string) {
	widths := computeWidths(groups, columns)
	// Header
	for _, c := range columns {
		fmt.Fprintf(w, "%s\t", padRight(columnTitle(c), widths[c]))
	}
	fmt.Fprintln(w)
	for _, g := range groups {
		for _, r := range g.Rows {
			for _, c := range columns {
				v := columnValue(r, c)
				fmt.Fprintf(w, "%s\t", padRight(v, widths[c]))
			}
			fmt.Fprintln(w)
		}
	}
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func centerPad(s string, n int) string {
	if len(s) >= n {
		return s
	}
	pad := n - len(s)
	left := pad / 2
	right := pad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

// Table uses "+----+" separators.
func renderTable(w io.Writer, groups []RowGroup, columns []string) {
	widths := computeWidths(groups, columns)
	sep := "+"
	for _, c := range columns {
		sep += strings.Repeat("-", widths[c]+2) + "+"
	}
	// Header
	fmt.Fprintln(w, sep)
	fmt.Fprint(w, "|")
	for _, c := range columns {
		fmt.Fprintf(w, " %s |", centerPad(columnTitle(c), widths[c]))
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, sep)
	// Rows
	for i, g := range groups {
		if i > 0 {
			fmt.Fprintln(w, sep)
		}
		for _, r := range g.Rows {
			fmt.Fprint(w, "|")
			for _, c := range columns {
				v := columnValue(r, c)
				// Left align, with padding
				fmt.Fprintf(w, " %s |", padRightTableCell(v, widths[c], c))
			}
			fmt.Fprintln(w)
		}
	}
	fmt.Fprintln(w, sep)
}

// padRightTableCell pads the cell value: profile/status are left-aligned (with padding),
// ip/domain are left-aligned too but centered is only for headers.
func padRightTableCell(v string, n int, col string) string {
	return padRight(v, n)
}

func renderMarkdown(w io.Writer, groups []RowGroup, columns []string) {
	widths := computeWidths(groups, columns)
	// Header
	fmt.Fprint(w, "|")
	for _, c := range columns {
		fmt.Fprintf(w, " %s |", centerPad(columnTitle(c), widths[c]))
	}
	fmt.Fprintln(w)
	// Separator (markdown)
	fmt.Fprint(w, "|")
	for _, c := range columns {
		fmt.Fprintf(w, "%s|", strings.Repeat("-", widths[c]+2))
	}
	fmt.Fprintln(w)
	for i, g := range groups {
		if i > 0 {
			// Inner separator for markdown with multiple groups
			fmt.Fprint(w, "|")
			for _, c := range columns {
				fmt.Fprintf(w, "%s|", strings.Repeat("-", widths[c]+2))
			}
			fmt.Fprintln(w)
		}
		for _, r := range g.Rows {
			fmt.Fprint(w, "|")
			for _, c := range columns {
				v := columnValue(r, c)
				fmt.Fprintf(w, " %s |", padRightTableCell(v, widths[c], c))
			}
			fmt.Fprintln(w)
		}
	}
}
