package cli

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

// FlagDef describes a single flag.
type FlagDef struct {
	Name      string
	Short     string // single letter, without dash, "" if none
	Type      string // "string", "bool", "duration", "stringslice"
	Default   string // textual default
	Help      string
	IsGlobal  bool
	Set       bool
	StringVal string
	BoolVal   bool
	DurationVal time.Duration
	StringSliceVal []string
}

// NewFlagSet returns an ordered list with lookup helpers.
type FlagSet struct {
	Order []*FlagDef
	ByLong  map[string]*FlagDef
	ByShort map[string]*FlagDef
}

func NewFlagSet() *FlagSet {
	return &FlagSet{
		ByLong:  map[string]*FlagDef{},
		ByShort: map[string]*FlagDef{},
	}
}

func (fs *FlagSet) Add(f *FlagDef) *FlagDef {
	fs.Order = append(fs.Order, f)
	fs.ByLong[f.Name] = f
	if f.Short != "" {
		fs.ByShort[f.Short] = f
	}
	// Initialize default values
	switch f.Type {
	case "duration":
		if f.Default != "" {
			d, err := time.ParseDuration(f.Default)
			if err == nil {
				f.DurationVal = d
			}
		}
	case "string":
		f.StringVal = f.Default
	case "bool":
		if f.Default == "true" {
			f.BoolVal = true
		}
	}
	return f
}

// Merge adds flags from another FlagSet as global.
func (fs *FlagSet) Merge(other *FlagSet, asGlobal bool) {
	for _, f := range other.Order {
		nf := *f // copy
		if asGlobal {
			nf.IsGlobal = true
		}
		fs.Order = append(fs.Order, &nf)
		fs.ByLong[nf.Name] = &nf
		if nf.Short != "" {
			fs.ByShort[nf.Short] = &nf
		}
	}
}

// Get string value or default.
func (fs *FlagSet) GetString(name string) string {
	if f, ok := fs.ByLong[name]; ok {
		return f.StringVal
	}
	return ""
}

func (fs *FlagSet) GetBool(name string) bool {
	if f, ok := fs.ByLong[name]; ok {
		return f.BoolVal
	}
	return false
}

func (fs *FlagSet) GetDuration(name string) time.Duration {
	if f, ok := fs.ByLong[name]; ok {
		return f.DurationVal
	}
	return 0
}

func (fs *FlagSet) GetStringSlice(name string) []string {
	if f, ok := fs.ByLong[name]; ok {
		return f.StringSliceVal
	}
	return nil
}

func (fs *FlagSet) IsSet(name string) bool {
	if f, ok := fs.ByLong[name]; ok {
		return f.Set
	}
	return false
}

// ParseArgs parses the argument list. Returns positional args and any error.
// Returns remaining positional args and an error.
func (fs *FlagSet) Parse(args []string) ([]string, error) {
	var positional []string
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			// Long option
			name := a[2:]
			var val string
			hasValAttached := false
			if idx := strings.Index(name, "="); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasValAttached = true
			}
			f, ok := fs.ByLong[name]
			if !ok {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if f.Type == "bool" {
				if hasValAttached {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return nil, fmt.Errorf("invalid bool value for --%s: %s", name, val)
					}
					f.BoolVal = b
				} else {
					f.BoolVal = true
				}
				f.Set = true
			} else {
				if !hasValAttached {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					val = args[i]
				}
				if err := setValue(f, val); err != nil {
					return nil, err
				}
				f.Set = true
			}
