			name := a[2:]
			var val string
			hasValAttached := false
			if idx := strings.Index(name, "="); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasValAttached = true
			}
			f, ok := fs.ByLong[name]
			if !ok {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if f.Type == "bool" {
				if hasValAttached {
					b, err := strconv.ParseBool(val)
					if err != nil {
						return nil, fmt.Errorf("invalid bool value for --%s: %s", name, val)
					}
					f.BoolVal = b
				} else {
					f.BoolVal = true
				}
				f.Set = true
			} else {
				if !hasValAttached {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					val = args[i]
				}
				if err := setValue(f, val); err != nil {
					return nil, err
				}
				f.Set = true
			}
		} else if len(a) > 1 && a[0] == '-' && a != "-" {
			// Short options; may be combined. Support -oVAL or -o VAL, or -abc
			rest := a[1:]
			for len(rest) > 0 {
				sh := string(rest[0])
				rest = rest[1:]
				f, ok := fs.ByShort[sh]
				if !ok {
					return nil, fmt.Errorf("unknown shorthand flag: '%s' in -%s", sh, a[1:])
				}
				if f.Type == "bool" {
					f.BoolVal = true
					f.Set = true
					continue
				}
				// Needs a value
				var val string
				if len(rest) > 0 {
					val = rest
					rest = ""
				} else {
					if i+1 >= len(args) {
						return nil, fmt.Errorf("flag needs an argument: -%s", sh)
					}
					i++
					val = args[i]
				}
				if err := setValue(f, val); err != nil {
					return nil, err
				}
				f.Set = true
			}
		} else {
			positional = append(positional, a)
		}
		i++
	}
	return positional, nil
}

func setValue(f *FlagDef, val string) error {
	switch f.Type {
	case "string":
		f.StringVal = val
	case "stringslice":
		parts := strings.Split(val, ",")
		for _, p := range parts {
			if p != "" {
				f.StringSliceVal = append(f.StringSliceVal, strings.TrimSpace(p))
			}
		}
	case "duration":
		d, err := time.ParseDuration(val)
		if err != nil {
			return fmt.Errorf("invalid duration for --%s: %s", f.Name, val)
		}
		f.DurationVal = d
	case "bool":
		b, err := strconv.ParseBool(val)
		if err != nil {
			return fmt.Errorf("invalid bool for --%s: %s", f.Name, val)
		}
		f.BoolVal = b
	}
	return nil
}

// HelpLines returns cobra-style formatted flag help lines.
func (fs *FlagSet) HelpLines(globalOnly bool) []string {
	// Collect rows to compute the column widths
	rows := [][2]string{}
	for _, f := range fs.Order {
		if globalOnly != f.IsGlobal {
			continue
		}
		left := formatFlagLeft(f)
		right := f.Help
		if f.Type == "string" && f.Default != "" {
			right = fmt.Sprintf(`%s (default "%s")`, right, f.Default)
		} else if f.Type == "duration" {
			// Cobra renders duration defaults by formatting the time.Duration
			if f.Default != "" {
				d, err := time.ParseDuration(f.Default)
				if err == nil {
					right = fmt.Sprintf("%s (default %s)", right, formatDurationCobra(d))
				}
			}
		} else if f.Type == "bool" && f.Default == "true" {
			right = fmt.Sprintf("%s (default true)", right)
		}
		rows = append(rows, [2]string{left, right})
	}
	// Find max left width
	maxLeft := 0
	for _, r := range rows {
		if len(r[0]) > maxLeft {
			maxLeft = len(r[0])
		}
	}
	lines := make([]string, 0, len(rows))
	for _, r := range rows {
		pad := strings.Repeat(" ", maxLeft-len(r[0])+3)
		lines = append(lines, fmt.Sprintf("  %s%s%s", r[0], pad, r[1]))
	}
	return lines
}

// formatFlagLeft returns e.g. "-f, --from string".
func formatFlagLeft(f *FlagDef) string {
	typeStr := ""
	switch f.Type {
	case "string":
		typeStr = " string"
	case "stringslice":
		typeStr = " strings"
	case "duration":
		typeStr = " duration"
	}
	if f.Short != "" {
		return fmt.Sprintf("-%s, --%s%s", f.Short, f.Name, typeStr)
	}
	return fmt.Sprintf("    --%s%s", f.Name, typeStr)
}

// formatDurationCobra mimics cobra's duration string formatting.
func formatDurationCobra(d time.Duration) string {
	return d.String()
}
EOF
echo done

