package cli

import (
	"io"
	"os"

	"hostctl/internal/hosts"
)

// Context is a collection of runtime data for command execution.
type Context struct {
	Args         []string
	Stdout       io.Writer
	LocalFlags   *FlagSet
	GlobalFlags  *FlagSet

	HostFile     string
	Quiet        bool
	OutputFormat string
	Columns      []string
	NoColor      bool

	Cmd          *Command
}

// ResolveGlobals reads common flags into ctx.
func (ctx *Context) ResolveGlobals() {
	ctx.HostFile = ctx.GlobalFlags.GetString("host-file")
	if ctx.HostFile == "" {
		ctx.HostFile = "/etc/hosts"
	}
	ctx.Quiet = ctx.GlobalFlags.GetBool("quiet")
	ctx.NoColor = ctx.GlobalFlags.GetBool("no-color")
	ctx.OutputFormat = ctx.GlobalFlags.GetString("out")
	if ctx.OutputFormat == "" {
		ctx.OutputFormat = "table"
	}
	if ctx.GlobalFlags.GetBool("raw") {
		ctx.OutputFormat = "raw"
	}
	ctx.Columns = ctx.GlobalFlags.GetStringSlice("column")
}

// LoadFile parses the hosts file.
func (ctx *Context) LoadFile() (*hosts.File, error) {
	return hosts.Parse(ctx.HostFile)
}

// PrintInfo prints the "Using hosts file" info unless quiet.
func (ctx *Context) PrintUsingHostFile() {
	if ctx.Quiet {
		return
	}
