package cli

import (
	"sort"
	"strings"

	"hostctl/internal/hosts"
	"hostctl/internal/render"
)

// filterProfiles filters `file`'s profiles by names. Empty names means no filter.
// Always includes "default" profile if it has entries.
func filterProfiles(file *hosts.File, names []string, includeDefault bool, onlyStatus string) []*hosts.Profile {
	wantSet := map[string]bool{}
	for _, n := range names {
		wantSet[n] = true
	}
	out := []*hosts.Profile{}
	// Always include default first if includeDefault is true
	if includeDefault && (len(names) == 0 || wantSet["default"]) {
		if def := buildDefault(file); def != nil {
			out = append(out, def)
		}
	}
	for _, p := range file.Profiles {
		if len(names) > 0 && !wantSet[p.Name] {
			continue
		}
		if onlyStatus != "" && p.Status != onlyStatus {
			continue
		}
		out = append(out, p)
	}
	return out
}

// buildDefault reads the default entries from the file.
func buildDefault(file *hosts.File) *hosts.Profile {
	p := &hosts.Profile{Name: "default", Status: "on", IPMap: map[string][]string{}}
	for _, line := range file.DefaultLines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		ip := fields[0]
		for _, d := range fields[1:] {
			if strings.HasPrefix(d, "#") {
				break
			}
			p.AddEntry(ip, d)
		}
	}
	if p.Count() == 0 {
		return nil
	}
	return p
}

// RenderProfiles writes the rendered output to ctx.Stdout.
func RenderProfiles(ctx *Context, profiles []*hosts.Profile, withEntries bool) {
	groups := render.BuildRows(profiles, withEntries)
	cols := render.AllColumns
	if !withEntries {
		cols = render.ColumnsForStatus
	}
	cols = render.FilterColumns(cols, ctx.Columns)
	render.Render(ctx.Stdout, groups, cols, ctx.OutputFormat)
}

// ensureProfileExists returns true if all provided profile names exist (not "default").
func ensureProfileExists(file *hosts.File, names []string) bool {
	for _, n := range names {
		if n == "default" {
			return false
		}
		if file.GetProfile(n) == nil {
			return false
		}
	}
	return true
}

// NonDefault returns names excluding "default".
func NonDefault(names []string) []string {
	out := []string{}
	for _, n := range names {
		if n != "default" {
			out = append(out, n)
		}
	}
	sort.Strings(out)
	return out
}
EOF
echo done

