cat > internal/cli/root.go <<'EOF'
package cli

import (
	"fmt"
	"os"
	"strings"
)

const version = "dev"

// Run is the main entry point.
func Run(args []string) int {
	ctx := NewContext()
	ctx.Stdout = os.Stdout
	root := buildRootCommand()
	ctx.Cmd = root
	return runCommand(ctx, root, args)
}

// runCommand dispatches to subcommand or runs the command.
func runCommand(ctx *Context, cmd *Command, args []string) int {
	// Short-circuit help/version: scan for known top-level flags separately.
	// First, extract any subcommand name if present (first non-flag arg).
	// Pre-scan: split args based on subcommand detection.
	if sub, rest, ok := detectSubcommand(cmd, args); ok {
		sub.Path = cmd.Fullname()
		ctx.Cmd = sub
		return runCommand(ctx, sub, rest)
	}
	// No subcommand; this command must be runnable.
	// Build local + global flag set
	merged := NewFlagSet()
	if cmd.LocalFlags != nil {
		for _, f := range cmd.LocalFlags.Order {
			merged.Add(copyFlag(f))
		}
	}
	if cmd.GlobalFlags != nil {
		for _, f := range cmd.GlobalFlags.Order {
			// Merge with IsGlobal
			nf := copyFlag(f)
			nf.IsGlobal = true
			merged.Add(nf)
		}
	}
	// Parse
	positional, err := merged.Parse(args)
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	// Check --help
	if helpFlag := merged.ByLong["help"]; helpFlag != nil && helpFlag.BoolVal {
		cmd.PrintHelp(ctx.Stdout)
		return 0
	}
	// Check --version for root
	if versionFlag := merged.ByLong["version"]; versionFlag != nil && versionFlag.BoolVal {
		fmt.Fprintf(ctx.Stdout, "hostctl version %s\n", version)
		return 0
	}
	// Attach to context
	ctx.LocalFlags = cmd.LocalFlags
	ctx.GlobalFlags = merged // Everything in merged
	ctx.Args = positional
	ctx.ResolveGlobals()
	// If command has no Run, show help
	if cmd.Run == nil {
		cmd.PrintHelp(ctx.Stdout)
		return 0
	}
	return cmd.Run(ctx)
}

// detectSubcommand checks if the first positional is a subcommand.
func detectSubcommand(cmd *Command, args []string) (*Command, []string, bool) {
	if len(cmd.SubCommands) == 0 {
		return nil, nil, false
	}
	// Walk args looking for first arg that is not a flag.
	// If we see a flag that expects a value, skip it.
	flagMap := map[string]*FlagDef{}
	shortMap := map[string]*FlagDef{}
	collectFlags := func(fs *FlagSet) {
		if fs == nil {
			return
		}
		for _, f := range fs.Order {
			flagMap[f.Name] = f
			if f.Short != "" {
				shortMap[f.Short] = f
			}
		}
	}
	collectFlags(cmd.LocalFlags)
	collectFlags(cmd.GlobalFlags)
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			if idx := strings.Index(name, "="); idx >= 0 {
				name = name[:idx]
				i++
				continue
			}
			if f, ok := flagMap[name]; ok {
				i++
				if f.Type != "bool" {
					i++
				}
				continue
			}
			// Unknown flag - skip one
			i++
			continue
		} else if len(a) > 1 && a[0] == '-' {
			// Short flag - may be combined, look at last char
			last := a[len(a)-1:]
			if f, ok := shortMap[last]; ok {
				i++
				if f.Type != "bool" && len(a) == 2 {
					i++
				}
				continue
			}
			i++
			continue
		}
		// First non-flag is a possible subcommand name
		for _, sc := range cmd.SubCommands {
			if sc.Name == a {
				return sc, append(append([]string{}, args[:i]...), args[i+1:]...), true
			}
			for _, alias := range sc.Aliases {
				if alias == a {
					return sc, append(append([]string{}, args[:i]...), args[i+1:]...), true
				}
			}
		}
		// Unknown subcommand
		// Fall through — at runtime we'll let parsing or Run decide.
		return nil, nil, false
	}
	return nil, nil, false
}

func copyFlag(f *FlagDef) *FlagDef {
	nf := *f
	// Reset runtime state so each copy is independent
	nf.Set = false
	nf.StringSliceVal = nil
	switch nf.Type {
	case "string":
		nf.StringVal = nf.Default
	case "bool":
		nf.BoolVal = nf.Default == "true"
	case "duration":
		if nf.Default != "" {
			// already parsed at Add
		}
	}
	return &nf
}
EOF
