package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"hostctl/internal/hosts"
)

// persistentFlags returns the global/persistent flags from root.
func persistentFlags() *FlagSet {
	fs := NewFlagSet()
	fs.Add(&FlagDef{Name: "column", Short: "c", Type: "stringslice", Help: "Column names to show on lists. comma separated"})
	fs.Add(&FlagDef{Name: "host-file", Type: "string", Default: "/etc/hosts", Help: "Hosts file path"})
	fs.Add(&FlagDef{Name: "no-color", Type: "bool", Help: "force colorless output"})
	fs.Add(&FlagDef{Name: "out", Short: "o", Type: "string", Default: "table", Help: "Output type (table|raw|markdown|json)"})
	fs.Add(&FlagDef{Name: "quiet", Short: "q", Type: "bool", Help: "Run command without output"})
	fs.Add(&FlagDef{Name: "raw", Type: "bool", Help: "Output without borders (same as -o raw)"})
	return fs
}

func buildRootCommand() *Command {
	global := persistentFlags()
	root := &Command{
		Name: "hostctl",
		Long: `hostctl is a CLI tool to manage your hosts file with ease.
You can have multiple profiles, enable/disable exactly what
you need each time with a simple interface.`,
		LocalFlags: func() *FlagSet {
			f := NewFlagSet()
			f.Add(&FlagDef{Name: "help", Short: "h", Type: "bool", Help: "help for hostctl"})
			f.Add(&FlagDef{Name: "version", Short: "v", Type: "bool", Help: "version for hostctl"})
			return f
		}(),
		GlobalFlags: nil, // root doesn't show Global Flags block
	}
	// Root has the persistent flags inline with the Flags: block
	// In cobra's root help, persistent flags appear with local flags combined.
	combined := NewFlagSet()
	// Order: -c, -h, --host-file, --no-color, -o, -q, --raw, -v
	combined.Add(&FlagDef{Name: "column", Short: "c", Type: "stringslice", Help: "Column names to show on lists. comma separated"})
	combined.Add(&FlagDef{Name: "help", Short: "h", Type: "bool", Help: "help for hostctl"})
	combined.Add(&FlagDef{Name: "host-file", Type: "string", Default: "/etc/hosts", Help: "Hosts file path"})
	combined.Add(&FlagDef{Name: "no-color", Type: "bool", Help: "force colorless output"})
	combined.Add(&FlagDef{Name: "out", Short: "o", Type: "string", Default: "table", Help: "Output type (table|raw|markdown|json)"})
	combined.Add(&FlagDef{Name: "quiet", Short: "q", Type: "bool", Help: "Run command without output"})
	combined.Add(&FlagDef{Name: "raw", Type: "bool", Help: "Output without borders (same as -o raw)"})
	combined.Add(&FlagDef{Name: "version", Short: "v", Type: "bool", Help: "version for hostctl"})
	root.LocalFlags = combined
	root.GlobalFlags = nil

	// Subcommands (alphabetical order for help list; cobra sorts them)
	root.SubCommands = []*Command{
		buildAdd(global),
		buildBackup(global),
		buildDisable(global),
		buildEnable(global),
		buildHelp(global),
		buildList(global),
		buildRemove(global),
		buildReplace(global),
		buildRestore(global),
		buildStatus(global),
		buildSync(global),
		buildToggle(global),
	}
	return root
}

func globalCopy(g *FlagSet) *FlagSet {
	out := NewFlagSet()
	for _, f := range g.Order {
		nf := *f
		out.Order = append(out.Order, &nf)
		out.ByLong[nf.Name] = &nf
		if nf.Short != "" {
			out.ByShort[nf.Short] = &nf
		}
	}
	return out
}

func helpFlag() *FlagDef {
	return &FlagDef{Name: "help", Short: "h", Type: "bool"}
}

// ------------------- add -------------------

func buildAdd(global *FlagSet) *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "from", Short: "f", Type: "string", Help: "file to read"})
	hf := helpFlag()
	hf.Help = "help for add"
	local.Add(hf)
	local.Add(&FlagDef{Name: "wait", Short: "w", Type: "duration", Default: "-1ns",
		Help: "Enables a profile for a specific amount of time. (example: 5m, 1h)"})
	cmd := &Command{
		Name:  "add",
		Short: "Add content to a profile in your hosts file.",
		Long: `Reads from a file and set content to a profile in your hosts file.
If the profile already exists it will be added to it.`,
		Usage:       "[profiles] [flags]",
		LocalFlags:  local,
		GlobalFlags: globalCopy(global),
		Run:         runAdd,
	}
	cmd.SubCommands = []*Command{buildAddDomains(global)}
	return cmd
}

func runAdd(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	if len(ctx.Args) > 1 {
		ctx.PrintError(fmt.Errorf("specify only one profile"))
		return 1
	}
	profile := ctx.Args[0]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	from := ctx.LocalFlags.GetString("from")
	entries, err := hosts.ReadEntriesFile(from)
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	// Find or create
	p := file.GetProfile(profile)
	if p == nil {
		// Mimic internal new profile
		p = newProfileHelper(profile, "on")
		file.AddProfile(p)
	}
	for _, e := range entries {
		p.AddEntry(e[0], e[1])
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	// Output list of profile's content
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	if !ctx.Quiet {
		ctx.Stdout.Write([]byte("\n"))
	}
	waitAndRemove(ctx, profile)
	return 0
}

func newProfileHelper(name, status string) *hosts.Profile {
	return &hosts.Profile{Name: name, Status: status, IPMap: map[string][]string{}}
}

// ------------------- add domains -------------------

func buildAddDomains(global *FlagSet) *Command {
	local := NewFlagSet()
	hf := helpFlag()
	hf.Help = "help for domains"
	local.Add(hf)
	local.Add(&FlagDef{Name: "ip", Type: "string", Default: "127.0.0.1", Help: "domains ip"})
	gf := globalCopy(global)
	// "wait" is on parent's persistent flags for subcommand "add"
	gf.Add(&FlagDef{Name: "wait", Short: "w", Type: "duration", Default: "-1ns",
		Help: "Enables a profile for a specific amount of time. (example: 5m, 1h)",
		IsGlobal: true})
	cmd := &Command{
		Name:       "domains",
		Short:      "Add content in your hosts file.",
		Long: `Set content in your hosts file.
If the profile already exists it will be added to it.`,
		Usage:      "[profile] [domains] [flags]",
		Aliases:    []string{"domain"},
		AliasUsage: "[profile] [domains] [flags]",
		LocalFlags: local,
		GlobalFlags: gf,
		Run:        runAddDomains,
	}
	return cmd
}

func runAddDomains(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	profile := ctx.Args[0]
	domains := ctx.Args[1:]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	ip := ctx.LocalFlags.GetString("ip")
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	p := file.GetProfile(profile)
	if p == nil {
		p = newProfileHelper(profile, "on")
		file.AddProfile(p)
	}
	for _, d := range domains {
		p.AddEntry(ip, d)
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Domains '%s' added.", strings.Join(domains, ", ")))
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	waitAndRemove(ctx, profile)
	return 0
}

// ------------------- backup -------------------

func buildBackup(global *FlagSet) *Command {
	local := NewFlagSet()
	hf := helpFlag()
	hf.Help = "help for backup"
	local.Add(hf)
	wd, _ := os.Getwd()
	local.Add(&FlagDef{Name: "path", Type: "string", Default: wd, Help: "A path to save the backup"})
	return &Command{
		Name:  "backup",
		Short: "Creates a backup copy of your hosts file",
		Long: `Creates a backup copy of your hosts file with the date in .YYYYMMDD
as extension.`,
		Usage:       "[flags]",
		LocalFlags:  local,
		GlobalFlags: globalCopy(global),
		Run:         runBackup,
	}
}

func runBackup(ctx *Context) int {
	ctx.PrintUsingHostFile()
	path := ctx.LocalFlags.GetString("path")
	data, err := os.ReadFile(ctx.HostFile)
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	base := filepath.Base(ctx.HostFile)
	dateStr := time.Now().Format("20060102")
	dest := filepath.Join(path, fmt.Sprintf("%s.%s", base, dateStr))
	if err := os.WriteFile(dest, data, 0644); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Backup '%s' created.", dest))
	// Print current list
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	profiles := filterProfiles(file, nil, true, "")
	RenderProfiles(ctx, profiles, true)
	return 0
}

// ------------------- disable -------------------

func buildDisable(global *FlagSet) *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "all", Type: "bool", Help: "Disable all profiles"})
	hf := helpFlag()
	hf.Help = "help for disable"
	local.Add(hf)
	local.Add(&FlagDef{Name: "only", Type: "bool", Help: "Enable all other profiles"})
	local.Add(&FlagDef{Name: "wait", Short: "w", Type: "duration", Default: "-1ns", Help: "Enables a profile for a specific amount of time"})
	return &Command{
		Name:  "disable",
		Short: "Disable a profile from your hosts file.",
		Long: `Disable a profile from your hosts file without removing it.
It will be listed as "off" while it is disabled.`,
		Usage:       "[profiles] [flags]",
		LocalFlags:  local,
		GlobalFlags: globalCopy(global),
		Run:         runDisable,
	}
