// waitAndRemove waits (if configured) and then removes the profile from the file.
func waitAndRemove(ctx *Context, profile string) {
	wait := ctx.LocalFlags.GetDuration("wait")
	if wait <= 0 {
		// Also check global
		if g := ctx.GlobalFlags.ByLong["wait"]; g != nil {
			wait = g.DurationVal
		}
	}
	if wait <= 0 {
		return
	}
	time.Sleep(wait)
	file, err := hosts.Parse(ctx.HostFile)
	if err != nil {
		return
	}
	file.RemoveProfile(profile)
	_ = file.Write()
}

