func globalCopy(g *FlagSet) *FlagSet {
	out := NewFlagSet()
	for _, f := range g.Order {
		nf := *f
		out.Order = append(out.Order, &nf)
		out.ByLong[nf.Name] = &nf
		if nf.Short != "" {
			out.ByShort[nf.Short] = &nf
		}
	}
	return out
