func runToggle(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	if len(ctx.Args) > 1 {
		// cobra doesn't explicitly enforce this here; but many profiles with same name would error
	}
	profile := ctx.Args[0]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	if len(ctx.Args) > 1 {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	p := file.GetProfile(profile)
	if p == nil {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	if p.Status == "on" {
		p.Status = "off"
	} else {
		p.Status = "on"
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	waitAndRemove(ctx, profile)
	return 0
}

// waitAndRemove waits (if configured) and then removes the profile from the file.
func waitAndRemove(ctx *Context, profile string) {
	wait := ctx.LocalFlags.GetDuration("wait")
	if wait <= 0 {
		// Also check global
		if g := ctx.GlobalFlags.ByLong["wait"]; g != nil {
			wait = g.DurationVal
		}
	}
	if wait <= 0 {
		return
	}
	time.Sleep(wait)
	file, err := hosts.Parse(ctx.HostFile)
	if err != nil {
		return
	}
	file.RemoveProfile(profile)
	_ = file.Write()
}

