		Short: fmt.Sprintf("Shows list of %s profiles on your hosts file.", name),
		Long:  fmt.Sprintf("Shows a detailed list of %s profiles on your hosts file with name, ip and host name.", name),
		Usage: "[flags]",
		Aliases: aliases,
		LocalFlags: local,
		GlobalFlags: globalCopy(global),
		Run: func(ctx *Context) int {
			ctx.PrintUsingHostFile()
			file, err := ctx.LoadFile()
			if err != nil {
				ctx.PrintError(err)
				return 1
			}
			profiles := filterProfiles(file, ctx.Args, true, status)
			if len(profiles) == 0 {
				return 0
			}
			RenderProfiles(ctx, profiles, true)
			return 0
		},
	}
}

// ------------------- remove -------------------

func buildRemove(global *FlagSet) *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "all", Type: "bool", Help: "Remove all profiles"})
	hf := helpFlag()
	hf.Help = "help for remove"
	local.Add(hf)
	cmd := &Command{
		Name:  "remove",
		Short: "Remove a profile from your hosts file.",
		Long: `Completely remove a profile content from your hosts file.
It cannot be undone unless you have a backup and restore it.

If you want to remove a profile but would like to use it later,
use 'hosts disable' instead.`,
		Usage:       "[profiles] [flags]",
		Aliases:     []string{"rm"},
		AliasUsage:  "[profiles] [flags]",
		LocalFlags:  local,
		GlobalFlags: globalCopy(global),
		Run:         runRemove,
	}
	cmd.SubCommands = []*Command{buildRemoveDomains(global)}
	return cmd
}

func runRemove(ctx *Context) int {
	all := ctx.LocalFlags.GetBool("all")
	if !all && len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	for _, n := range ctx.Args {
		if n == "default" {
			ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
			return 1
		}
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	if !all && !ensureProfileExists(file, ctx.Args) {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	var removed []string
	if all {
		for _, p := range file.Profiles {
			removed = append(removed, p.Name)
		}
		file.Profiles = nil
		file.ProfByName().ResetAll()
	} else {
		for _, n := range ctx.Args {
			file.RemoveProfile(n)
			removed = append(removed, n)
		}
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(removed, ", ")))
	if !ctx.Quiet {
		ctx.Stdout.Write([]byte("\n"))
	}
	return 0
}

func buildRemoveDomains(global *FlagSet) *Command {
	local := NewFlagSet()
	hf := helpFlag()
	hf.Help = "help for domains"
	local.Add(hf)
	return &Command{
		Name:       "domains",
		Short:      "Remove domains from your hosts file.",
		Long: `Completely remove domains from your hosts file.
It cannot be undone unless you have a backup and restore it.`,
		Usage:      "[profile] [domains] [flags]",
		Aliases:    []string{"domain"},
		AliasUsage: "[profile] [domains] [flags]",
		LocalFlags: local,
		GlobalFlags: globalCopy(global),
		Run:        runRemoveDomains,
	}
}

func runRemoveDomains(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	profile := ctx.Args[0]
	domains := ctx.Args[1:]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	p := file.GetProfile(profile)
	if p == nil {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	for _, d := range domains {
		p.RemoveDomain(d)
	}
	removedProfile := false
	if p.Count() == 0 {
		file.RemoveProfile(profile)
		removedProfile = true
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))
	if removedProfile {
		ctx.PrintSuccess(fmt.Sprintf("Profile '%s' removed.", profile))
		return 0
	}
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	return 0
}

