	if c.Long != "" {
		fmt.Fprintln(w)
		fmt.Fprintln(w, strings.TrimRight(c.Long, "\n"))
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Usage:")
	if c.IsRoot {
		// Root only shows "hostctl [command]"
		fmt.Fprintf(w, "  %s [command]\n", c.Fullname())
	} else {
