		fmt.Fprintln(w, "Aliases:")
		aliasList := append([]string{c.Name}, c.Aliases...)
		if c.AliasUsage != "" {
			fmt.Fprintf(w, "  %s %s\n", strings.Join(aliasList, ", "), c.AliasUsage)
		} else {
			fmt.Fprintf(w, "  %s\n", strings.Join(aliasList, ", "))
		}
	}
	if len(c.SubCommands) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Available Commands:")
		// Find max name length
		maxLen := 0
		for _, sc := range c.SubCommands {
			if len(sc.Name) > maxLen {
				maxLen = len(sc.Name)
			}
		}
		colWidth := maxLen + 1
		if colWidth < 12 {
			colWidth = 12
		}
		for _, sc := range c.SubCommands {
			pad := strings.Repeat(" ", colWidth-len(sc.Name))
			fmt.Fprintf(w, "  %s%s%s\n", sc.Name, pad, sc.Short)
		}
	}
	if c.LocalFlags != nil {
		lines := c.LocalFlags.HelpLines(false)
		if len(lines) > 0 {
			fmt.Fprintln(w)
			fmt.Fprintln(w, "Flags:")
			for _, l := range lines {
				fmt.Fprintln(w, l)
			}
		}
	}
	if c.GlobalFlags != nil {
		lines := c.GlobalFlags.HelpLines(true)
		if len(lines) > 0 {
			fmt.Fprintln(w)
			fmt.Fprintln(w, "Global Flags:")
			for _, l := range lines {
				fmt.Fprintln(w, l)
			}
		}
	}
	if len(c.SubCommands) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintf(w, "Use \"%s [command] --help\" for more information about a command.\n", c.Fullname())
	}
}
