package cli

import (
	"fmt"
	"io"
	"sort"
	"strings"
)

// Command describes a CLI command for help rendering.
type Command struct {
	Name            string
	Short           string
	Long            string
	Usage           string // e.g. "[profiles] [flags]"
	Aliases         []string
	AliasUsage      string
	SubCommands     []*Command
	LocalFlags      *FlagSet
	PersistentFlags *FlagSet
	Parent          *Command
	IsRoot          bool
	Run             func(ctx *Context) int
	Path            string
}

func (c *Command) Fullname() string {
	if c.Path == "" {
		return c.Name
	}
	return c.Path + " " + c.Name
}

// CollectLocalFlags returns LocalFlags + PersistentFlags (own), sorted by long name.
func (c *Command) CollectLocalFlags() []*FlagDef {
	var out []*FlagDef
	seen := map[string]bool{}
	if c.LocalFlags != nil {
		for _, f := range c.LocalFlags.Order {
			if !seen[f.Name] {
				out = append(out, f)
				seen[f.Name] = true
			}
		}
	}
	if c.PersistentFlags != nil {
		for _, f := range c.PersistentFlags.Order {
			if !seen[f.Name] {
				out = append(out, f)
				seen[f.Name] = true
			}
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// CollectGlobalFlags returns PersistentFlags inherited from ancestors, sorted.
func (c *Command) CollectGlobalFlags() []*FlagDef {
	var out []*FlagDef
	seen := map[string]bool{}
	for p := c.Parent; p != nil; p = p.Parent {
		if p.PersistentFlags != nil {
			for _, f := range p.PersistentFlags.Order {
				if !seen[f.Name] {
					out = append(out, f)
					seen[f.Name] = true
				}
			}
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// CollectAllAvailableFlags returns all flags (local + persistent + inherited) for parsing.
func (c *Command) CollectAllAvailableFlags() []*FlagDef {
	local := c.CollectLocalFlags()
	global := c.CollectGlobalFlags()
	out := append([]*FlagDef{}, local...)
	for _, f := range global {
		out = append(out, f)
	}
	return out
}

// PrintHelp prints cobra-style help.
func (c *Command) PrintHelp(w io.Writer) {
	if c.Long != "" {
		fmt.Fprintln(w)
		fmt.Fprintln(w, strings.TrimRight(c.Long, "\n"))
	}
	fmt.Fprintln(w)
	fmt.Fprintln(w, "Usage:")
	if c.IsRoot {
		fmt.Fprintf(w, "  %s [command]\n", c.Fullname())
	} else {
		if c.Run != nil && c.Usage != "" {
			fmt.Fprintf(w, "  %s %s\n", c.Fullname(), c.Usage)
		} else if c.Run != nil {
			fmt.Fprintf(w, "  %s\n", c.Fullname())
		}
		if len(c.SubCommands) > 0 {
			fmt.Fprintf(w, "  %s [command]\n", c.Fullname())
		}
	}
	if len(c.Aliases) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Aliases:")
		aliasList := append([]string{c.Name}, c.Aliases...)
		if c.AliasUsage != "" {
			fmt.Fprintf(w, "  %s %s\n", strings.Join(aliasList, ", "), c.AliasUsage)
		} else {
			fmt.Fprintf(w, "  %s\n", strings.Join(aliasList, ", "))
		}
	}
	if len(c.SubCommands) > 0 {
