		fmt.Fprintln(w, "Available Commands:")
		maxLen := 0
		subs := make([]*Command, len(c.SubCommands))
		copy(subs, c.SubCommands)
		sort.Slice(subs, func(i, j int) bool { return subs[i].Name < subs[j].Name })
		for _, sc := range subs {
