				}
			}
		case "bool":
			if f.Default == "true" {
				right = fmt.Sprintf("%s (default true)", right)
			}
		}
		rows = append(rows, [2]string{left, right})
	}
	maxLeft := 0
	for _, r := range rows {
		if len(r[0]) > maxLeft {
