	return fs
}

func detectSubcommand(cmd *Command, args []string) (*Command, []string, bool) {
	if len(cmd.SubCommands) == 0 {
		return nil, nil, false
	}
	allFlags := cmd.CollectAllAvailableFlags()
	flagMap := map[string]*FlagDef{}
	shortMap := map[string]*FlagDef{}
	for _, f := range allFlags {
		flagMap[f.Name] = f
		if f.Short != "" {
			shortMap[f.Short] = f
		}
	}
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			if idx := strings.Index(name, "="); idx >= 0 {
				name = name[:idx]
				i++
				continue
			}
			if f, ok := flagMap[name]; ok {
				i++
				if f.Type != "bool" {
					i++
				}
				continue
			}
			i++
			continue
		} else if len(a) > 1 && a[0] == '-' {
			last := a[len(a)-1:]
			if f, ok := shortMap[last]; ok {
				i++
				if f.Type != "bool" && len(a) == 2 {
					i++
				}
				continue
			}
			i++
			continue
		}
		for _, sc := range cmd.SubCommands {
			if sc.Name == a {
				return sc, append(append([]string{}, args[:i]...), args[i+1:]...), true
			}
			for _, alias := range sc.Aliases {
				if alias == a {
					return sc, append(append([]string{}, args[:i]...), args[i+1:]...), true
				}
			}
		}
		// Unknown name — treat as positional argument
		return nil, nil, false
	}
	return nil, nil, false
}
