	base := filepath.Base(ctx.HostFile)
	dateStr := time.Now().Format("20060102")
	dest := filepath.Join(path, fmt.Sprintf("%s.%s", base, dateStr))
	if err := os.WriteFile(dest, data, 0644); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Backup '%s' created.", dest))
	file, err := ctx.LoadFile()
	if err != nil {
