func runAdd(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	if len(ctx.Args) > 1 {
		ctx.PrintError(fmt.Errorf("specify only one profile"))
		return 1
	}
	profile := ctx.Args[0]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	from := ctx.LocalFlags.GetString("from")
	entries, err := hosts.ReadEntriesFile(from)
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	p := file.GetProfile(profile)
	if p == nil {
		p = newProfileHelper(profile, "on")
		file.AddProfile(p)
	}
	for _, e := range entries {
		p.AddEntry(e[0], e[1])
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	if !ctx.Quiet {
		ctx.Stdout.Write([]byte("\n"))
	}
	waitAndRemove(ctx, profile)
	return 0
}

