func runRemove(ctx *Context) int {
	all := ctx.LocalFlags.GetBool("all")
	if !all && len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	for _, n := range ctx.Args {
		if n == "default" {
			ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
			return 1
		}
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	if !all && !ensureProfileExists(file, ctx.Args) {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	var removed []string
	if all {
		for _, p := range file.Profiles {
			removed = append(removed, p.Name)
		}
		file.Profiles = nil
		file.ProfByName().ResetAll()
	} else {
		for _, n := range ctx.Args {
			file.RemoveProfile(n)
			removed = append(removed, n)
		}
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(removed, ", ")))
