func runStatus(ctx *Context) int {
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	wantNames := ctx.Args
	list := []*hosts.Profile{}
	wantSet := map[string]bool{}
	for _, n := range wantNames {
		wantSet[n] = true
	}
	for _, p := range file.Profiles {
		if len(wantNames) > 0 && !wantSet[p.Name] {
			continue
