func runStatusChange(ctx *Context, desired string) int {
	all := ctx.LocalFlags.GetBool("all")
	only := ctx.LocalFlags.GetBool("only")
	if all && len(ctx.Args) > 0 {
		ctx.PrintUsingHostFile()
		ctx.PrintError(fmt.Errorf("args must be empty with --all flag"))
		return 1
	}
	if !all && len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	for _, n := range ctx.Args {
		if n == "default" {
			ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
			return 1
		}
	}
	if !all && !ensureProfileExists(file, ctx.Args) {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	opposite := "on"
	if desired == "on" {
		opposite = "off"
	}
	if all {
		for _, p := range file.Profiles {
			p.Status = desired
		}
	} else {
		argSet := map[string]bool{}
		for _, n := range ctx.Args {
			argSet[n] = true
		}
		for _, p := range file.Profiles {
			if argSet[p.Name] {
				p.Status = desired
			} else if only {
				p.Status = opposite
			}
		}
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	var showNames []string
	var includeDefault bool
	if all {
		showNames = nil
		includeDefault = true
	} else {
		showNames = ctx.Args
		includeDefault = false
	}
	profiles := filterProfiles(file, showNames, includeDefault, "")
	RenderProfiles(ctx, profiles, true)
	if !ctx.Quiet {
		ctx.Stdout.Write([]byte("\n"))
	}
	if len(ctx.Args) == 1 {
		waitAndRemove(ctx, ctx.Args[0])
	}
	return 0
}

