	}
	for _, n := range ctx.Args {
		if n == "default" {
			ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
			return 1
		}
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	if !all && !ensureProfileExists(file, ctx.Args) {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	var removed []string
	if all {
		for _, p := range file.Profiles {
			removed = append(removed, p.Name)
		}
		file.Profiles = nil
		file.ProfByName().ResetAll()
	} else {
		for _, n := range ctx.Args {
			file.RemoveProfile(n)
			removed = append(removed, n)
		}
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(removed, ", ")))
	if !ctx.Quiet {
		ctx.Stdout.Write([]byte("\n"))
	}
	return 0
}

func buildRemoveDomains() *Command {
	local := NewFlagSet()
	local.Add(helpFlag("domains"))
	return &Command{
		Name:       "domains",
		Short:      "Remove domains from your hosts file.",
		Long: `Completely remove domains from your hosts file.
It cannot be undone unless you have a backup and restore it.`,
		Usage:      "[profile] [domains] [flags]",
		Aliases:    []string{"domain"},
		AliasUsage: "[profile] [domains] [flags]",
		LocalFlags: local,
		Run:        runRemoveDomains,
	}
}

func runRemoveDomains(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	profile := ctx.Args[0]
	domains := ctx.Args[1:]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	p := file.GetProfile(profile)
	if p == nil {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	for _, d := range domains {
		p.RemoveDomain(d)
	}
	removedProfile := false
	if p.Count() == 0 {
		file.RemoveProfile(profile)
		removedProfile = true
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))
	if removedProfile {
		ctx.PrintSuccess(fmt.Sprintf("Profile '%s' removed.", profile))
		return 0
	}
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	return 0
}

// ------------------- replace -------------------

func buildReplace() *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "from", Short: "f", Type: "string", Help: "file to read"})
	local.Add(helpFlag("replace"))
	return &Command{
		Name:  "replace",
		Short: "Replace content to a profile in your hosts file.",
		Long: `Reads from a file and set content to a profile in your hosts file.
If the profile already exists it will be overwritten.`,
		Usage:      "[profile] [flags]",
		LocalFlags: local,
		Run:        runReplace,
	}
}

func runReplace(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	if len(ctx.Args) > 1 {
		ctx.PrintError(fmt.Errorf("specify only one profile"))
		return 1
	}
	profile := ctx.Args[0]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	from := ctx.LocalFlags.GetString("from")
	entries, err := hosts.ReadEntriesFile(from)
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	p := newProfileHelper(profile, "on")
	for _, e := range entries {
		p.AddEntry(e[0], e[1])
	}
	file.AddProfile(p)
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	return 0
}

// ------------------- restore -------------------

func buildRestore() *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "from", Type: "string", Help: "The file to restore from"})
	local.Add(helpFlag("restore"))
	return &Command{
		Name:  "restore",
		Short: "Restore hosts file content from a backup file.",
		Long: `Reads from a file and replace the content of your hosts file.

WARNING: the complete hosts file will be overwritten with the backup data.`,
		Usage:      "[flags]",
		LocalFlags: local,
		Run:        runRestore,
	}
}

func runRestore(ctx *Context) int {
	ctx.PrintUsingHostFile()
	from := ctx.LocalFlags.GetString("from")
	data, err := os.ReadFile(from)
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	if err := os.WriteFile(ctx.HostFile, data, 0644); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintSuccess(fmt.Sprintf("File '%s' restored.", from))
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	profiles := filterProfiles(file, nil, true, "")
	RenderProfiles(ctx, profiles, true)
	return 0
}

// ------------------- status -------------------

func buildStatus() *Command {
	local := NewFlagSet()
	local.Add(helpFlag("status"))
	return &Command{
		Name:  "status",
		Short: "Shows a list of profile names and statuses on your hosts file.",
		Long: `Shows a list of unique profile names on your hosts file with its status.

The "default" profile is always on and will be skipped.`,
		Usage:      "[profiles] [flags]",
		LocalFlags: local,
		Run:        runStatus,
	}
}

func runStatus(ctx *Context) int {
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	wantNames := ctx.Args
	list := []*hosts.Profile{}
	wantSet := map[string]bool{}
	for _, n := range wantNames {
		wantSet[n] = true
	}
	for _, p := range file.Profiles {
		if len(wantNames) > 0 && !wantSet[p.Name] {
			continue
		}
		list = append(list, p)
	}
	if len(list) == 0 {
		return 0
	}
	RenderProfiles(ctx, list, false)
	return 0
}

// ------------------- sync -------------------

func buildSync() *Command {
	local := NewFlagSet()
	local.Add(helpFlag("sync"))
	persistent := NewFlagSet()
	persistent.Add(&FlagDef{Name: "wait", Short: "w", Type: "duration", Default: "-1ns", Help: "Enables a profile for a specific amount of time"})
	cmd := &Command{
		Name:            "sync",
		Short:           "Sync some system IPs with a profile.",
		Long:            `Reads IPs and names from some local system and sync it with a profile in your hosts file.`,
		LocalFlags:      local,
		PersistentFlags: persistent,
	}
	cmd.SubCommands = []*Command{
		buildSyncDocker(),
		buildSyncDockerCompose(),
	}
	for _, sc := range cmd.SubCommands {
		sc.Parent = cmd
	}
	return cmd
}

func buildSyncDocker() *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "domain", Short: "d", Type: "string", Default: "loc", Help: "domain where your docker containers will be added"})
	local.Add(helpFlag("docker"))
	local.Add(&FlagDef{Name: "network", Type: "string", Help: "Filter containers from a specific network"})
	return &Command{
		Name:       "docker",
		Short:      "Sync your Docker containers IPs with a profile.",
		Long:       `Reads from Docker the list of containers and add names and IPs to a profile in your hosts file.`,
		Usage:      "[profile] [flags]",
		LocalFlags: local,
		Run:        runSyncDocker,
	}
}

func runSyncDocker(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	ctx.PrintUsingHostFile()
	ctx.PrintError(fmt.Errorf("Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?"))
	return 1
}

func buildSyncDockerCompose() *Command {
	local := NewFlagSet()
	local.Add(&FlagDef{Name: "compose-file", Type: "string", Help: "path to docker-compose.yml"})
	local.Add(&FlagDef{Name: "domain", Short: "d", Type: "string", Default: "loc", Help: "domain where your docker containers will be added"})
	local.Add(helpFlag("docker-compose"))
	local.Add(&FlagDef{Name: "network", Type: "string", Help: "Filter containers from a specific network"})
	local.Add(&FlagDef{Name: "prefix", Type: "bool", Help: "keep project name prefix from domain name"})
	local.Add(&FlagDef{Name: "project-name", Type: "string", Help: "docker compose project name"})
	return &Command{
		Name:       "docker-compose",
		Short:      "Sync your docker-compose containers IPs with a profile.",
		Long:       `Reads from a docker-compose.yml file  the list of containers and add names and IPs to a profile in your hosts file.`,
		Usage:      "[profile] [flags]",
		LocalFlags: local,
		Run:        runSyncDockerCompose,
	}
}

func runSyncDockerCompose(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	ctx.PrintUsingHostFile()
	composeFile := ctx.LocalFlags.GetString("compose-file")
	if composeFile == "" {
		wd, _ := os.Getwd()
		composeFile = filepath.Join(wd, "docker-compose.yml")
	}
	if _, err := os.ReadFile(composeFile); err != nil {
		ctx.PrintError(err)
		return 1
	}
	ctx.PrintError(fmt.Errorf("docker-compose sync not implemented"))
	return 1
}

// ------------------- toggle -------------------

func buildToggle() *Command {
	local := NewFlagSet()
	local.Add(helpFlag("toggle"))
	local.Add(&FlagDef{Name: "wait", Short: "w", Type: "duration", Default: "-1ns", Help: "Toggles a profile for a specific amount of time"})
	return &Command{
		Name:  "toggle",
		Short: "Change status of a profile on your hosts file.",
		Long:  `Alternates between on/off status of an existing profile.`,
		Usage:      "[flags]",
		LocalFlags: local,
		Run:        runToggle,
	}
}

func runToggle(ctx *Context) int {
	if len(ctx.Args) == 0 {
		ctx.PrintError(fmt.Errorf("missing profile name"))
		return 1
	}
	profile := ctx.Args[0]
	if profile == "default" {
		ctx.PrintError(fmt.Errorf("'default' profile should not be handled by hostctl"))
		return 1
	}
	ctx.PrintUsingHostFile()
	file, err := ctx.LoadFile()
	if err != nil {
		ctx.PrintError(err)
		return 1
	}
	if len(ctx.Args) > 1 {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	p := file.GetProfile(profile)
	if p == nil {
		ctx.PrintError(fmt.Errorf("unknown profile name"))
		return 1
	}
	if p.Status == "on" {
		p.Status = "off"
	} else {
		p.Status = "on"
	}
	if err := file.Write(); err != nil {
		ctx.PrintError(err)
		return 1
	}
	profiles := filterProfiles(file, []string{profile}, false, "")
	RenderProfiles(ctx, profiles, true)
	waitAndRemove(ctx, profile)
	return 0
}

func waitAndRemove(ctx *Context, profile string) {
	wait := ctx.LocalFlags.GetDuration("wait")
	if wait <= 0 {
		wait = ctx.GlobalFlags.GetDuration("wait")
	}
	if wait <= 0 {
		return
	}
	time.Sleep(wait)
	file, err := hosts.Parse(ctx.HostFile)
	if err != nil {
		return
	}
	file.RemoveProfile(profile)
	_ = file.Write()
}
