func ParseReader(path string, r io.Reader) (*File, error) {
	file := NewFile(path)
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 64*1024), 10*1024*1024)
	var all []string
	for scanner.Scan() {
		all = append(all, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}

	// Find the managed header (3 lines). The header pattern is:
	//   ##################################################################
	//   # Content under this line is handled by hostctl. DO NOT EDIT.
	//   ##################################################################
	hashLine := "##################################################################"
	managedStart := -1
	for i := 0; i+2 < len(all); i++ {
		if all[i] == hashLine && strings.HasPrefix(all[i+1], "# Content under") && all[i+2] == hashLine {
			managedStart = i
			break
		}
	}
	var defaultLines, managedLines []string
	if managedStart < 0 {
		defaultLines = all
	} else {
		defaultLines = all[:managedStart]
		managedLines = all[managedStart+3:]
	}
	// Trim trailing blank lines from defaultLines
	for len(defaultLines) > 0 && strings.TrimSpace(defaultLines[len(defaultLines)-1]) == "" {
		defaultLines = defaultLines[:len(defaultLines)-1]
	}
	file.DefaultLines = defaultLines

	// Parse managed profiles.
	var cur *Profile
	for _, line := range managedLines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if cur == nil {
			if m := profileStartRe.FindStringSubmatch(trimmed); m != nil {
				cur = newProfile(m[2], m[1])
			}
			continue
		}
		if endRe.MatchString(trimmed) {
