cat > internal/render/render.go <<'EOF'
package render

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"hostctl/internal/hosts"
)

type Row struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

var AllColumns = []string{"profile", "status", "ip", "domain"}
var ColumnsForStatus = []string{"profile", "status"}

func columnTitle(c string) string { return strings.ToUpper(c) }

func columnValue(r Row, col string) string {
	switch col {
	case "profile":
		return r.Profile
	case "status":
		return r.Status
	case "ip":
		return r.IP
	case "domain":
		return r.Host
	}
	return ""
}

func FilterColumns(all []string, wanted []string) []string {
	if len(wanted) == 0 {
		return all
	}
	set := map[string]bool{}
	for _, c := range all {
		set[c] = true
	}
	out := []string{}
	for _, c := range wanted {
		lc := strings.ToLower(strings.TrimSpace(c))
		if set[lc] {
			out = append(out, lc)
		}
	}
	if len(out) == 0 {
		return all
	}
	return out
}

type RowGroup struct {
	Name string
	Rows []Row
}

// BuildRows creates rows for the given profiles. If withEntries=false, one row per profile (status-style), and all rows are in one group.
func BuildRows(profiles []*hosts.Profile, withEntries bool) []RowGroup {
	if !withEntries {
		// Single group for status mode
		rows := []Row{}
		for _, p := range profiles {
			rows = append(rows, Row{Profile: p.Name, Status: p.Status})
		}
		if len(rows) == 0 {
			return nil
		}
		return []RowGroup{{Name: "", Rows: rows}}
	}
	groups := []RowGroup{}
	for _, p := range profiles {
		entries := p.Entries()
		if len(entries) == 0 {
			continue
		}
		g := RowGroup{Name: p.Name}
		for _, e := range entries {
			g.Rows = append(g.Rows, Row{
				Profile: p.Name,
				Status:  p.Status,
				IP:      e.IP,
				Host:    e.Domain,
			})
		}
		groups = append(groups, g)
	}
	return groups
}

func Render(w io.Writer, groups []RowGroup, columns []string, format string) {
	if format == "json" {
		renderJSON(w, groups, columns)
		return
	}
	if len(groups) == 0 {
		return
	}
	switch format {
	case "raw":
		renderRaw(w, groups, columns)
	case "markdown":
		renderMarkdown(w, groups, columns)
	default:
		renderTable(w, groups, columns)
	}
}

func renderJSON(w io.Writer, groups []RowGroup, columns []string) {
	rows := []Row{}
