			fmt.Fprint(w, "|")
			for _, c := range columns {
				fmt.Fprintf(w, "%s|", strings.Repeat("-", widths[c]+2))
			}
			fmt.Fprintln(w)
		}
		for _, r := range g.Rows {
			fmt.Fprint(w, "|")
			for _, c := range columns {
				v := columnValue(r, c)
				fmt.Fprintf(w, " %s |", padRight(v, widths[c]))
			}
			fmt.Fprintln(w)
		}
	}
}
