package cli

import (
	"io"
	"os"

	"hostctl/internal/hosts"
)

// Context is runtime data for command execution.
type Context struct {
	Args         []string
	Stdout       io.Writer
	LocalFlags   *FlagSet
	GlobalFlags  *FlagSet

	HostFile     string
	Quiet        bool
	OutputFormat string
	Columns      []string
	NoColor      bool

	Cmd          *Command
}

func (ctx *Context) ResolveGlobals() {
	ctx.HostFile = ctx.GlobalFlags.GetString("host-file")
	if ctx.HostFile == "" {
		ctx.HostFile = "/etc/hosts"
	}
	ctx.Quiet = ctx.GlobalFlags.GetBool("quiet")
	ctx.NoColor = ctx.GlobalFlags.GetBool("no-color")
	ctx.OutputFormat = ctx.GlobalFlags.GetString("out")
	if ctx.OutputFormat == "" {
		ctx.OutputFormat = "table"
	}
	if ctx.GlobalFlags.GetBool("raw") {
		ctx.OutputFormat = "raw"
	}
	ctx.Columns = ctx.GlobalFlags.GetStringSlice("column")
}

func (ctx *Context) LoadFile() (*hosts.File, error) {
	return hosts.Parse(ctx.HostFile)
}

// PrintUsingHostFile prints the info unless suppressed.
func (ctx *Context) PrintUsingHostFile() {
	if ctx.Quiet || ctx.OutputFormat == "json" {
		return
	}
	printInfo(ctx.Stdout, "Using hosts file: "+ctx.HostFile)
	ctx.Stdout.Write([]byte("\n"))
}

// PrintSuccess prints success unless suppressed.
func (ctx *Context) PrintSuccess(msg string) {
	if ctx.Quiet || ctx.OutputFormat == "json" {
		return
	}
	printSuccess(ctx.Stdout, msg)
	ctx.Stdout.Write([]byte("\n"))
}

func (ctx *Context) PrintError(err error) {
	printError(ctx.Stdout, err.Error())
}

func (ctx *Context) Err() io.Writer { return ctx.Stdout }

func NewContext() *Context { return &Context{Stdout: os.Stdout} }
EOF
