		entries := p.Entries()
		if len(entries) == 0 {
			continue
		}
		g := RowGroup{Name: p.Name}
		for _, e := range entries {
			g.Rows = append(g.Rows, Row{
				Profile: p.Name,
				Status:  p.Status,
				IP:      e.IP,
				Host:    e.Domain,
			})
		}
		groups = append(groups, g)
	}
	return groups
