	Headers     []string // lowercased column names (as specified by user)
	DataColumns []string // known columns in user-order (subset of Headers)
}

// ResolveColumns creates a ColumnPlan from the defaults and user's input.
func ResolveColumns(defaults []string, user []string) *ColumnPlan {
	if len(user) == 0 {
		return &ColumnPlan{Headers: defaults, DataColumns: defaults}
	}
	headers := []string{}
	data := []string{}
	hasValid := false
	for _, c := range user {
