	if format == "json" {
		renderJSON(w, groups)
		return
	}
	if len(plan.Headers) == 0 || len(groups) == 0 {
		return
	}
	switch format {
	case "raw":
		renderRaw(w, groups, plan)
	case "markdown":
		renderMarkdown(w, groups, plan)
	default:
		renderTable(w, groups, plan)
	}
