// filterProfiles filters `file`'s profiles by names.
func filterProfiles(file *hosts.File, names []string, includeDefault bool, onlyStatus string) []*hosts.Profile {
	wantSet := map[string]bool{}
	for _, n := range names {
		wantSet[n] = true
	}
	out := []*hosts.Profile{}
	if includeDefault && (len(names) == 0 || wantSet["default"]) {
