			out = append(out, def)
		}
	}
	for _, p := range file.Profiles {
		if len(names) > 0 && !wantSet[p.Name] {
			continue
		}
		if onlyStatus != "" && p.Status != onlyStatus {
			continue
		}
		out = append(out, p)
	}
	return out
}

func buildDefault(file *hosts.File) *hosts.Profile {
	p := &hosts.Profile{Name: "default", Status: "on", IPMap: map[string][]string{}}
	for _, line := range file.DefaultLines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			continue
		}
		ip := fields[0]
		for _, d := range fields[1:] {
			if strings.HasPrefix(d, "#") {
				break
			}
			p.AddEntry(ip, d)
		}
	}
	if p.Count() == 0 {
		return nil
	}
	return p
}

func RenderProfiles(ctx *Context, profiles []*hosts.Profile, withEntries bool) {
	if ctx.Quiet {
		return
	}
	groups := render.BuildRows(profiles, withEntries)
	defaults := render.AllColumns
	if !withEntries {
		defaults = render.ColumnsForStatus
	}
	plan := render.ResolveColumns(defaults, ctx.Columns)
	render.Render(ctx.Stdout, groups, plan, ctx.OutputFormat)
}

func ensureProfileExists(file *hosts.File, names []string) bool {
	for _, n := range names {
		if n == "default" {
			return false
		}
		if file.GetProfile(n) == nil {
			return false
		}
	}
	return true
}

func NonDefault(names []string) []string {
	out := []string{}
	for _, n := range names {
		if n != "default" {
			out = append(out, n)
		}
	}
	sort.Strings(out)
	return out
}
