		renderRaw(w, groups, plan)
	case "markdown":
		renderMarkdown(w, groups, plan)
	default:
		renderTable(w, groups, plan)
	}
}

func renderJSON(w io.Writer, groups []RowGroup) {
	rows := []Row{}
	for _, g := range groups {
		rows = append(rows, g.Rows...)
	}
	if rows == nil {
		rows = []Row{}
	}
	data, _ := json.Marshal(rows)
	fmt.Fprintln(w, string(data))
}

// computeWidths computes the column widths.
// For each column at index i: width = max(len(header), len(values at index i in each row))
func computeWidths(groups []RowGroup, plan *ColumnPlan) []int {
	n := len(plan.Headers)
	widths := make([]int, n)
	for i, c := range plan.Headers {
		widths[i] = len(columnTitle(c))
	}
	// Values align to the DataColumns (at positions 0..len(DataColumns)-1).
	for _, g := range groups {
		for _, r := range g.Rows {
			for i, c := range plan.DataColumns {
				v := columnValue(r, c)
				if len(v) > widths[i] {
					widths[i] = len(v)
				}
			}
		}
	}
	return widths
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func centerPad(s string, n int) string {
	if len(s) >= n {
		return s
	}
	pad := n - len(s)
	left := pad / 2
	right := pad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func renderRaw(w io.Writer, groups []RowGroup, plan *ColumnPlan) {
	widths := computeWidths(groups, plan)
	n := len(plan.Headers)
	for i, c := range plan.Headers {
		if i < n-1 {
			fmt.Fprintf(w, "%s\t", padRight(columnTitle(c), widths[i]))
		} else {
			fmt.Fprintln(w, padRight(columnTitle(c), widths[i]+1))
		}
	}
	dn := len(plan.DataColumns)
	for _, g := range groups {
		for _, r := range g.Rows {
			for i := 0; i < dn; i++ {
				v := columnValue(r, plan.DataColumns[i])
				fmt.Fprintf(w, "%s\t", padRight(v, widths[i]))
			}
			fmt.Fprintln(w)
		}
	}
}

func renderTable(w io.Writer, groups []RowGroup, plan *ColumnPlan) {
	widths := computeWidths(groups, plan)
	sep := "+"
	for _, wv := range widths {
