// ResolveColumns creates a ColumnPlan from the defaults and user's input.
func ResolveColumns(defaults []string, user []string) *ColumnPlan {
	if len(user) == 0 {
		return &ColumnPlan{Headers: defaults, DataColumns: defaults}
	}
	headers := []string{}
