# rerun tests
test_cmd() {
  local name="$1"
  shift
  cp /tmp/test/hosts.orig /tmp/test/h
  out1=$(./executable "$@" --host-file /tmp/test/h 2>&1)
  f1=$(cat /tmp/test/h)
  cp /tmp/test/hosts.orig /tmp/test/h
  out2=$(./hostctl "$@" --host-file /tmp/test/h 2>&1)
  f2=$(cat /tmp/test/h)
  diff_output=$(diff <(echo "$out1") <(echo "$out2"))
  files_diff=$(diff <(echo "$f1") <(echo "$f2"))
  if [ -n "$diff_output" ] || [ -n "$files_diff" ]; then
    echo "=== DIFF: $name ==="
    if [ -n "$diff_output" ]; then echo "OUTPUT:"; echo "$diff_output"; fi
    if [ -n "$files_diff" ]; then echo "FILE:"; echo "$files_diff"; fi
  fi
}

